  summary <- icc_df %>%
    filter(subset == "overall") %>%
    summarise(
      min  = round(min(ICC2k), 2),
      max  = round(max(ICC2k), 2),
      mean = round(mean(ICC2k), 2))

  cat(sprintf(
    "For %s, ICC(2,k) ranged from %.2f to %.2f (M = %.2f).\n",
    text_type, summary$min, summary$max, summary$mean))
